DROP TABLE IF EXISTS company_next;
DROP TABLE IF EXISTS gram_next;
DROP TABLE IF EXISTS posting_next;
DROP TABLE IF EXISTS city_next;
CREATE TABLE company_next (corporate_number TEXT PRIMARY KEY, core TEXT NOT NULL, legal_form TEXT, lg_code TEXT, name TEXT) WITHOUT ROWID;
