CREATE TABLE posting_next (g TEXT NOT NULL, lg_code TEXT NOT NULL, corporate_number TEXT NOT NULL, PRIMARY KEY (g, lg_code, corporate_number)) WITHOUT ROWID;
CREATE TABLE city_next (lg_code TEXT PRIMARY KEY, prefecture_name TEXT NOT NULL, city_name TEXT NOT NULL) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) WITHOUT ROWID;
